            action: "ATTACH_CONDITIONS" | "DETACH_CONDITIONS" | "SET_STATUS" | "SET_AUTOMATION_STATUS" | "SET_OWNER" | "ADD_TAGS" | "SUBMIT_FOR_REVIEW" | "MOVE_TO_SUITE";
